$run('Custom status URL cannot switch to another port on the configured host',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'custom','custom_url'=>'https://api.example.com/visualize','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10));$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function(){return array('code'=>200,'body'=>json_encode(array('statusUrl'=>'https://api.example.com:8443/job')));};$cookie=str_repeat('2',32);$_COOKIE['rk_ai_viz']=$cookie;$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$stateKey='rk_ai_viz_flooring_'.substr(hash('sha256',$cookie),0,32);t_error((new Engine())->generate('flooring',request_generate($f)),'rk_viz_provider','non-origin status port');t_eq(get_transient($stateKey)['used'],0,'unsafe status URL did not refund quota');unset($GLOBALS['wp_filters']['rk_ai_visualizer_http']);unlink($f);});
$run('Quota reservation fails closed when transient storage cannot persist',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'mock','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10));$cookie=str_repeat('3',32);$_COOKIE['rk_ai_viz']=$cookie;$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$stateKey='rk_ai_viz_flooring_'.substr(hash('sha256',$cookie),0,32);$GLOBALS['fail_transient_keys']=array($stateKey);t_error((new Engine())->generate('flooring',request_generate($f)),'rk_viz_quota_storage','failed reservation write');t_assert(false===get_transient($stateKey),'quota state unexpectedly persisted');unset($GLOBALS['fail_transient_keys']);unlink($f);});
