$run('Per-IP limiting rejects requests before image file parsing',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'mock','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>1));$_COOKIE['rk_ai_viz']=str_repeat('4',32);$_SERVER['REMOTE_ADDR']='192.0.2.45';$r=new WP_REST_Request();$r->params['options']=json_encode(valid_options());t_error((new Engine())->generate('flooring',$r),'rk_viz_no_image','first missing-file request');$ipKey='rk_ai_viz_ip_'.substr(hash_hmac('sha256','192.0.2.45','rk-ai-test-salt-auth'),0,24);t_assert(isset($GLOBALS['wp_transients'][$ipKey]),'rate-limit key is not keyed by WordPress salt');t_assert(!isset($GLOBALS['wp_transients']['rk_ai_viz_ip_'.substr(hash('sha256','192.0.2.45'),0,24)]),'unsalted IP hash remains in transient keys');$limited=(new Engine())->generate('flooring',$r);t_assert($limited instanceof WP_REST_Response,'IP limiter should return REST response');t_eq($limited->get_status(),429,'IP cap not enforced before upload parsing');});
$run('Gemini parser rejects malformed nested provider JSON without warnings',function(){update_option('rk_ai_visualizer_settings',array('gemini_key'=>'fake-unit-test-key'));$tmp=tempnam(sys_get_temp_dir(),'rk-gemini-');file_put_contents($tmp,test_png(20,20));$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function(){return array('code'=>200,'body'=>json_encode(array('candidates'=>array('not-an-object'))));};set_error_handler(function($severity,$message){throw new ErrorException($message,0,$severity);});try{$result=Factory::create('gemini')->generate(array('image_path'=>$tmp,'mime_type'=>'image/png','prompt'=>'test'));}finally{restore_error_handler();unset($GLOBALS['wp_filters']['rk_ai_visualizer_http']);@unlink($tmp);}t_assert(is_wp_error($result),'malformed Gemini response should be rejected');});
$run('Async provider adapters reject non-2xx polling responses',function(){$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function(){return array('code'=>503,'body'=>json_encode(array('status'=>'processing')));};update_option('rk_ai_visualizer_settings',array('custom_url'=>'https://api.example.com/status','hf_token'=>'fake-token'));$custom=Factory::create('custom')->poll(array('status_url'=>'https://api.example.com/status/job'));t_assert(is_wp_error($custom),'custom poll treated HTTP 503 as pending');$hf=Factory::create('huggingface')->poll(array('status_url'=>'https://router.huggingface.co/fal-ai/job/status?_subdomain=queue','response_url'=>'https://router.huggingface.co/fal-ai/job/result?_subdomain=queue'));t_assert(is_wp_error($hf),'Hugging Face poll treated HTTP 503 as pending');$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function(){return array('code'=>200,'body'=>json_encode(array('status'=>array('processing'))));};$badCustom=Factory::create('custom')->poll(array('status_url'=>'https://api.example.com/status/job'));$badHf=Factory::create('huggingface')->poll(array('status_url'=>'https://router.huggingface.co/fal-ai/job/status?_subdomain=queue','response_url'=>'https://router.huggingface.co/fal-ai/job/result?_subdomain=queue'));t_assert(is_wp_error($badCustom),'custom adapter accepted array status');t_assert(is_wp_error($badHf),'Hugging Face adapter accepted array status');$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function(){return array('code'=>200,'body'=>json_encode(array('images'=>'not-an-array')));};set_error_handler(function($severity,$message){throw new ErrorException($message,0,$severity);});try{$badImages=Factory::create('custom')->poll(array('status_url'=>'https://api.example.com/status/job'));}finally{restore_error_handler();}t_assert(is_wp_error($badImages),'custom adapter accepted malformed image list');$calls=0;$GLOBALS['wp_filters']['rk_ai_visualizer_http']=function()use(&$calls){$calls++;return array('code'=>200,'body'=>1===$calls?json_encode(array('status'=>'COMPLETED')):json_encode(array('images'=>'not-an-array')));};$badHfImages=Factory::create('huggingface')->poll(array('status_url'=>'https://router.huggingface.co/fal-ai/job/status?_subdomain=queue','response_url'=>'https://router.huggingface.co/fal-ai/job/result?_subdomain=queue'));t_assert(is_wp_error($badHfImages),'Hugging Face adapter accepted malformed image list');unset($GLOBALS['wp_filters']['rk_ai_visualizer_http']);});
$run('Kitchen definition registers with the expected independent field contract',function(){$d=Registry::instance()->get('kitchen');t_assert($d instanceof \RK\AIVisualizer\Definitions\Definition,'Kitchen definition missing from registry');t_eq($d->get('slug'),'kitchen');t_eq($d->get('name'),'Kitchen Visualizer');$ids=array_map(function($f){return $f['id'];},$d->fields());t_eq($ids,array('roomType','kitchenLayout','cabinetStyle','cabinetColor','countertopMaterial','countertopColor','backsplashStyle','backsplashMaterial','backsplashColor','flooring','hardwareFinish','applianceStyle','lightingPreference','customDesignInstructions'));});
$run('Kitchen fields validate selections and reject unknown values',function(){$d=Registry::instance()->get('kitchen');$v=Validation::fields(kitchen_valid_options(array('kitchenLayout'=>'island','cabinetColor'=>'sage')),$d);t_assert(is_array($v),'valid Kitchen options rejected');t_eq($v['kitchenLayout'],'island');t_eq($v['cabinetColor'],'sage');t_error(Validation::fields(kitchen_valid_options(array('countertopMaterial'=>'laminate')),$d),'rk_viz_bad_options','unknown Kitchen material');});
$run('Kitchen custom design field is conditionally visible and required',function(){$d=Registry::instance()->get('kitchen');t_error(Validation::fields(kitchen_valid_options(array('cabinetStyle'=>'custom')),$d),'rk_viz_bad_options','missing custom Kitchen instructions');$v=Validation::fields(kitchen_valid_options(array('cabinetStyle'=>'custom','customDesignInstructions'=>'  Narrow shaker rails with reeded glass  ')),$d);t_assert(is_array($v),'custom Kitchen instructions rejected');t_eq($v['customDesignInstructions'],'Narrow shaker rails with reeded glass');$hidden=Validation::fields(kitchen_valid_options(array('customDesignInstructions'=>'ignore when hidden')),$d);t_eq($hidden['customDesignInstructions'],'','hidden Kitchen instructions retained');});
$run('Kitchen prompt composes choices, custom instructions, allowed changes, and preservation rules',function(){$d=Registry::instance()->get('kitchen');$v=Validation::fields(kitchen_valid_options(array('kitchenLayout'=>'island','cabinetStyle'=>'custom','cabinetColor'=>'sage','countertopMaterial'=>'quartz','customDesignInstructions'=>'Use narrow shaker rails with reeded glass.')),$d);$p=Prompt::build($d,$v);foreach(array('island-centered cabinet and work-zone arrangement','custom cabinet style described by the user','muted sage green','quartz countertops','Custom user instruction: Use narrow shaker rails with reeded glass.','Only the selected cabinet fronts/colors','Preserve the original room architecture','original camera position') as $needle)t_assert(false!==strpos($p,$needle),'Kitchen prompt missing: '.$needle);});
$run('Generic renderer renders Kitchen definition fields and conditional metadata',function(){$html=Renderer::shortcode(array('visualizer'=>'kitchen'));foreach(array('data-visualizer="kitchen"','name="roomType"','name="kitchenLayout"','value="island"','name="countertopMaterial"','name="backsplashMaterial"','name="customDesignInstructions"','data-visible-field="cabinetStyle"','data-required-field="cabinetStyle"','Upload a kitchen photo') as $needle)t_assert(false!==strpos($html,$needle),'Kitchen renderer missing '.$needle);});
$run('Generic Engine generates Kitchen with mock provider and consumes its own quota',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'mock','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10));$cookie=str_repeat('9',32);$_COOKIE['rk_ai_viz']=$cookie;$f=tempnam(sys_get_temp_dir(),'rkimg');file_put_contents($f,test_png());$result=(new Engine())->generate('kitchen',request_generate($f,kitchen_valid_options()));t_assert($result instanceof WP_REST_Response,'Kitchen generation did not return REST response');t_eq($result->get_data()['status'],'success');$key='rk_ai_viz_kitchen_'.substr(hash('sha256',$cookie),0,32);$state=get_transient($key);t_assert(is_array($state),'Kitchen quota state was not stored');t_eq($state['used'],1,'Kitchen quota was not consumed');unlink($f);});
$run('Generic REST resolves Kitchen quota and lead flow by slug',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'mock','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10));$_COOKIE['rk_ai_viz']=str_repeat('l',32);$_SERVER['REMOTE_ADDR']='198.51.100.220';$quotaRequest=new WP_REST_Request('GET','/rk-ai/v1/visualizer/kitchen/quota');$quotaRequest->params['visualizer']='kitchen';$quota=\RK\AIVisualizer\Rest\Routes::quota($quotaRequest);t_assert(is_array($quota)&&!empty($quota['available']),'Kitchen quota REST resolution failed');t_eq($quota['visualizer'],'kitchen');$leadRequest=new WP_REST_Request('POST','/rk-ai/v1/visualizer/kitchen/lead');$leadRequest->params['visualizer']='kitchen';$leadRequest->json=array('name'=>'Kitchen Test','email'=>'kitchen-definition@example.com');$lead=\RK\AIVisualizer\Rest\Routes::lead($leadRequest);t_assert($lead instanceof WP_REST_Response,'Kitchen lead REST flow failed');t_eq($lead->get_data()['visualizer'],'kitchen');$found=false;foreach(Leads::all() as $stored){if('kitchen-definition@example.com'===$stored['email']){$found=true;t_eq($stored['visualizer'],'kitchen');}}t_assert($found,'Kitchen lead was not stored with its visualizer slug');});
$run('Flooring definition, prompt, and default renderer remain unchanged',function(){$d=Registry::instance()->get('flooring');$ids=array_map(function($f){return $f['id'];},$d->fields());t_eq($ids,array('roomType','projectType','preferredStyle','customStyleDescription','woodSpecies','floorDirection','finishPreference','sheen','serviceCity','squareFootage'));$values=Validation::fields(valid_options(array('woodSpecies'=>'hickory','preferredStyle'=>'gray_weathered','floorDirection'=>'herringbone')),$d);$p=Prompt::build($d,$values);foreach(array('Replace ONLY the existing visible floor','hickory hardwood','gray, weathered tone','herringbone','Do not change the walls.') as $needle)t_assert(false!==strpos($p,$needle),'Flooring regression prompt missing '.$needle);$html=Renderer::shortcode();t_assert(false!==strpos($html,'data-visualizer="flooring"'),'default Flooring shortcode changed');t_assert(false===strpos($html,'name="kitchenLayout"'),'Kitchen fields leaked into Flooring renderer');});
$run('Bootstrap registers namespaced REST, shortcode, assets, and admin callbacks',function(){$expected=array(array('rest_api_init',\RK\AIVisualizer\Rest\Routes::class,'register'),array('wp_enqueue_scripts',\RK\AIVisualizer\Frontend\Assets::class,'register'),array('admin_menu',\RK\AIVisualizer\Admin\Settings::class,'menu'),array('admin_init',\RK\AIVisualizer\Admin\Settings::class,'register'));foreach($expected as $want){$found=false;foreach($GLOBALS['wp_actions'] as $hook){if($hook[0]===$want[0]&&is_array($hook[1])&&$hook[1][0]===$want[1]&&$hook[1][1]===$want[2]){$found=true;break;}}t_assert($found,'missing or unresolved callback '.$want[0].' -> '.$want[1].'::'.$want[2]);}$shortcode=isset($GLOBALS['wp_shortcodes']['rk_ai_visualizer'])?$GLOBALS['wp_shortcodes']['rk_ai_visualizer']:array();t_eq($shortcode,array(\RK\AIVisualizer\Frontend\Renderer::class,'shortcode'),'shortcode callback did not resolve to Renderer');});
$run('Conditional field hidden state is protected from theme display rules',function(){$css=file_get_contents(dirname(__DIR__).'/assets/css/visualizer.css');t_assert(false!==strpos($css,'.rkaiviz [hidden]{display:none!important}'),'generic hidden override missing');});
$run('Repeated lead unlock accepts an unchanged persisted transient state',function(){update_option('rk_ai_visualizer_settings',array('enabled'=>true,'provider'=>'mock','free_count'=>2,'bonus_count'=>1,'cooldown_hours'=>24,'ip_per_hour'=>10));$_COOKIE['rk_ai_viz']=str_repeat('f',32);$_SERVER['REMOTE_ADDR']='203.0.113.87';$request=new WP_REST_Request('POST','/rk-ai/v1/visualizer/flooring/lead');$request->json=array('name'=>'Transient Idempotency QA','email'=>'transient-idempotency@example.com');$GLOBALS['wp_transient_false_on_noop']=true;$engine=new Engine();$first=$engine->lead('flooring',$request);$second=$engine->lead('flooring',$request);t_assert($first instanceof WP_REST_Response,'initial lead request failed');t_assert($second instanceof WP_REST_Response,'unchanged lead state was misreported as a storage failure');t_eq($second->get_status(),200);t_eq($second->get_data()['hasLead'],true);$matches=array_filter(Leads::all(),function($lead){return $lead['email']==='transient-idempotency@example.com';});t_eq(count($matches),1,'duplicate lead should remain deduplicated');unset($GLOBALS['wp_transient_false_on_noop']);});
$run('Settings sanitizer safely ignores array-shaped values and preserves saved secrets',function(){update_option('rk_ai_visualizer_settings',array('provider'=>'mock','hf_token'=>'saved-hf-token','gemini_key'=>'saved-gemini-key','custom_key'=>'saved-custom-key'));set_error_handler(function($severity,$message){throw new ErrorException($message,0,$severity);});try{$s=\RK\AIVisualizer\Admin\Settings::sanitize(array('enabled'=>array('1'),'provider'=>array('custom'),'hf_token'=>array('new'),'clear_hf_token'=>array('1'),'gemini_key'=>array('new'),'custom_key'=>array('new'),'custom_url'=>array('https://evil.example'),'gemini_model'=>array('model'),'custom_header'=>array('X-Key'),'free_count'=>array('10')));}finally{restore_error_handler();}t_eq($s['hf_token'],'saved-hf-token','malformed secret should preserve old secret');t_eq($s['gemini_key'],'saved-gemini-key','malformed Gemini key should preserve old secret');t_eq($s['custom_key'],'saved-custom-key','malformed custom key should preserve old secret');t_eq($s['custom_url'],'','malformed URL should be rejected');$credentialUrl=\RK\AIVisualizer\Admin\Settings::sanitize(array('custom_url'=>'https://user:pass@api.example.com/generate'));t_eq($credentialUrl['custom_url'],'','custom-provider URL must not store embedded credentials');t_eq($s['gemini_model'],'gemini-2.5-flash-image','malformed model should use safe default');t_eq($s['custom_header'],'Authorization','malformed header should use safe default');t_eq($s['enabled'],false,'malformed enabled flag should not enable plugin');$long=\RK\AIVisualizer\Admin\Settings::sanitize(array('gemini_key'=>str_repeat('x',4097)));t_eq($long['gemini_key'],'','oversized credential should be rejected');});
$run('Storage cleanup is portable and removes only old generated image files',function(){$dir=$GLOBALS['wp_upload_test'].'/rk-ai-visualizer';if(!is_dir($dir))mkdir($dir,0755,true);$old=$dir.'/old-phase4.jpg';$text=$dir.'/keep-phase4.txt';$fresh=$dir.'/fresh-phase4.png';file_put_contents($old,'old');file_put_contents($text,'keep');file_put_contents($fresh,'fresh');touch($old,time()-8*86400);\RK\AIVisualizer\Core\Storage::cleanup();t_assert(!file_exists($old),'expired image was not removed');t_assert(file_exists($text),'non-image file was removed');t_assert(file_exists($fresh),'recent image was removed');unlink($text);unlink($fresh);});
echo "\n$tests tests, $failed failures\n"; exit($failed?1:0);
